import { SegmentationConfig } from '@/types/touch-helper';
import { type GameConfig } from './config';

export async function fightLoop(conf: GameConfig) {
  Thread.sleep(2000);
  const color = conf.monsterColor;
  log(`[Task] 开始找怪，颜色: ${color}`);


  // 1. 截图
  const img = Device.capture();

  // 2. 应用滤镜处理
  // Step 1: BinarizationFilter
  img.applyFilter({
    "binarization": {
      "mode": "manual",
      "thresholdMin": 0,
      "thresholdMax": 72,
      "isRgbAvg": true,
      "sauvolaK": 0.20000000298023224,
      "windowSize": 15
    }
  });
  // Step 2: BlackWhiteInvertFilter
  img.applyFilter({
    "blackWhiteInvert": {
      "mode": "autoToWhiteBg"
    }
  });

  const config: SegmentationConfig = {
    "mode": "connectedComp",
    "padding": 0,
    "minWidth": 10,
    "minHeight": 10,
    "maxWidth": 0,
    "maxHeight": 0,
    "mergeDistance": 0,
    "startX": 0,
    "startY": 0,
    "cellWidth": 32,
    "cellHeight": 32,
    "colCount": 1,
    "rowCount": 1,
    "colGap": 0,
    "rowGap": 0,
    "splitRows": true,
    "splitCols": true,
    "projectionThreshold": 128
  };

  // 4. 字库数据 (Hex压缩)
  const fontLibrary = {
    "1": ""
  };

  // 5. 执行识别
  const result = img.ocrGrid(config, fontLibrary, 0.8);
  log(`识别结果: ${result}`);

  for (let i = 0; i < 3; i++) {
    // Colors 是全局对象
    const point = Colors.findColorPoint(color);
    if (point) {
      log(`Found monster at ${point[0]}, ${point[1]}`);
      Device.click(point[0], point[1]);
      await Thread.sleep(2000);
    } else {
      log("未发现怪物...");
      await Thread.sleep(1000);
    }
  }
}

